use std::env;

fn main() {
    // On rassemble tous les arguments dans un vecteur de String.
    let args: Vec<String> = env::args().collect();

    // args[0] est le nom du programme, on l'ignore.
    println!("Nombre d'arguments utiles : {}", args.len() - 1);
    for argument in &args[1..] {   // on emprunte, on ne consomme pas le vecteur
        println!("argument : {argument}");
    }
}

use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();

    // On vérifie qu'on a bien reçu deux arguments utiles.
    if args.len() < 3 {
        eprintln!("Usage : grep-mini <motif> <fichier>");
        return;   // on arrête proprement si un argument manque
    }

    let motif = &args[1];     // le texte à chercher
    let chemin = &args[2];    // le fichier où chercher
    println!("Recherche de « {motif} » dans « {chemin} »");
}

struct Config {
    motif: String,
    chemin: String,
}

impl Config {
    // Fonction associée : construit un Config ou renvoie un message d'erreur.
    fn build(args: &[String]) -> Result<Config, String> {
        if args.len() < 3 {
            return Err(String::from("Usage : grep-mini <motif> <fichier>"));
        }
        // On clone car Config possède ses propres String.
        let motif = args[1].clone();
        let chemin = args[2].clone();
        Ok(Config { motif, chemin })
    }
}

use std::fs;

// La fonction de recherche travaille avec des &str (emprunts, pas de copie).
// Elle renvoie les lignes de `contenu` qui contiennent `motif`.
fn rechercher<'a>(motif: &str, contenu: &'a str) -> Vec<&'a str> {
    let mut resultats = Vec::new();
    for ligne in contenu.lines() {
        if ligne.contains(motif) {
            resultats.push(ligne);   // on pousse une tranche (slice) du contenu
        }
    }
    resultats
}

// Renvoie un Result : `?` propage une éventuelle erreur de lecture.
fn executer(config: &Config) -> Result<(), std::io::Error> {
    let contenu = fs::read_to_string(&config.chemin)?;   // propage l'erreur si échec
    for ligne in rechercher(&config.motif, &contenu) {
        println!("{ligne}");
    }
    Ok(())
}

