use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Gestion de l'erreur de configuration (argument manquant).
    let config = match Config::build(&args) {
        Ok(config) => config,
        Err(message) => {
            eprintln!("{message}");
            return;
        }
    };

    // Gestion de l'erreur de lecture du fichier.
    if let Err(erreur) = executer(&config) {
        eprintln!("Erreur de lecture : {erreur}");
    }
}

