// On compare tout en minuscules. `to_lowercase()` crée une String,
// donc on passe une référence &str à `contains` via &motif_minuscule.
fn rechercher_insensible<'a>(motif: &str, contenu: &'a str) -> Vec<&'a str> {
    let motif_minuscule = motif.to_lowercase();
    let mut resultats = Vec::new();
    for ligne in contenu.lines() {
        if ligne.to_lowercase().contains(&motif_minuscule) {
            resultats.push(ligne);   // on renvoie la ligne d'origine, pas sa version minuscule
        }
    }
    resultats
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn insensible_a_la_casse() {
        let motif = "rUsT";
        let contenu = "\
J'apprends Rust.
Deuxième ligne.";
        assert_eq!(vec!["J'apprends Rust."], rechercher_insensible(motif, contenu));
    }
}
